inputs.default:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Part extracted from a datasheet",
  "type": "object",
  "required": [
    "part_number",
    "manufacturer",
    "package",
    "pins",
    "supply",
    "interfaces",
    "confidence"
  ],
  "additionalProperties": false,
  "properties": {
    "part_number": {
      "type": "string",
      "pattern": "^[A-Z0-9][A-Z0-9-]{3,}$"
    },
    "manufacturer": {
      "type": "string",
      "minLength": 2
    },
    "package": {
      "enum": [
        "LQFP48",
        "LQFP64",
        "LQFP100",
        "QFN32",
        "QFN48",
        "UFBGA176",
        "WLCSP49"
      ]
    },
    "pins": {
      "type": "integer",
      "minimum": 1,
      "maximum": 1024
    },
    "supply": {
      "$ref": "#/$defs/range"
    },
    "temp_c": {
      "$ref": "#/$defs/range"
    },
    "interfaces": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/iface"
      },
      "minItems": 1,
      "uniqueItems": true
    },
    "flash_kb": {
      "type": [
        "integer",
        "null"
      ],
      "minimum": 0
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "notes": {
      "type": "string",
      "maxLength": 200
    }
  },
  "$defs": {
    "range": {
      "type": "object",
      "required": [
        "min",
        "max"
      ],
      "additionalProperties": false,
      "properties": {
        "min": {
          "type": "number"
        },
        "max": {
          "type": "number"
        },
        "unit": {
          "enum": [
            "V",
            "°C"
          ]
        }
      }
    },
    "iface": {
      "type": "object",
      "required": [
        "kind",
        "count"
      ],
      "additionalProperties": false,
      "properties": {
        "kind": {
          "enum": [
            "UART",
            "SPI",
            "I2C",
            "CAN",
            "USB",
            "ETH",
            "SDIO"
          ]
        },
        "count": {
          "type": "integer",
          "minimum": 1
        }
      }
    }
  }
}

